    return (
        <CardDragSurface
            data-card-path={cardPath}
            data-dragging={isDragging ? 'true' : undefined}
            data-selected={isSelected ? 'true' : undefined}
            onContextMenu={onContextMenu}
            onDragOver={onDragOver}
            onDrop={onDrop}
            ref={setCardElement}
